static int split_cycle_name(char *raw_name, char **name_out) {
    char *dot = strchr(raw_name, '.');
    if (!dot || dot == raw_name) {
        *name_out = raw_name;
        return 0;
    }
    for (char *p = raw_name; p < dot; p++) {
        if (!isdigit((unsigned char)*p)) {
            *name_out = raw_name;
            return 0;
        }
    }
    *dot = 0;
    *name_out = dot + 1;
    return atoi(raw_name);
}

